// Aggregate Node ကနေ လာတဲ့ data array
const items = $input.all()[0].json.data;

const stats = {};

items.forEach(item => {
  const name =
    item.authorMeta?.name ||
    item.authorMeta?.nickName ||
    "Unknown";

  if (!stats[name]) {
    stats[name] = {
      post_count: 0,
      total_views: 0,
      total_likes: 0,
      total_comments: 0,
      total_shares: 0,
      posts: []
    };
  }

  stats[name].post_count += 1;
  stats[name].total_views += item.playCount || 0;
  stats[name].total_likes += item.diggCount || 0;
  stats[name].total_comments += item.commentCount || 0;
  stats[name].total_shares += item.shareCount || 0;

  stats[name].posts.push({
    text: item.text,
    views: item.playCount || 0,
    likes: item.diggCount || 0,
    comments: item.commentCount || 0,
    shares: item.shareCount || 0,
    date: item.createTimeISO
  });
});

return {
  summary: stats,
  raw_count_text: Object.keys(stats)
    .map(name => `${name}: ${stats[name].post_count} posts`)
    .join(", "),
  marketing_ready: true
};

