// ===================================================
// TIKTOK NORMALIZE + SMART BRAND RESOLUTION (UPGRADE)
// ===================================================

// ----------------------------
// 1️⃣ Helpers
// ----------------------------
function toNumber(v) {
  const n = Number(v);
  return isNaN(n) ? 0 : n;
}

function normalizeKey(str) {
  if (!str) return "";
  return String(str)
    .toLowerCase()
    .replace(/[^a-z0-9]/g, ""); // remove _, ., space, etc.
}

function formatMyanmarDate(dateObj) {
  if (!dateObj || isNaN(dateObj)) return null;

  const date = new Intl.DateTimeFormat("en-GB", {
    timeZone: "Asia/Yangon",
    day: "2-digit",
    month: "short",
    year: "numeric",
  }).format(dateObj);

  const time = new Intl.DateTimeFormat("en-US", {
    timeZone: "Asia/Yangon",
    hour: "2-digit",
    minute: "2-digit",
    hour12: true,
  }).format(dateObj);

  return `${date}, ${time}`;
}

function timeBucket(hour) {
  if (hour >= 6 && hour < 10) return "Morning (6–10 AM)";
  if (hour >= 10 && hour < 14) return "Midday (10 AM–2 PM)";
  if (hour >= 14 && hour < 18) return "Afternoon (2–6 PM)";
  if (hour >= 18 && hour < 22) return "Evening (6–10 PM)";
  return "Late Night (10 PM–6 AM)";
}

function dayTypeFromTimestamp(ts) {
  const day = new Date(ts).getDay();
  return day === 0 || day === 6 ? "Weekend" : "Weekday";
}

// ----------------------------
// 2️⃣ Canonical Brand Map (Normalized Keys)
// ----------------------------
const brandMap = {
  "agbcommunication": "AGB Communication",
  "novalink": "Novalink",
  "novalinkinternet": "Novalink",
  "u9myanmar": "U9",
  "5bbbroadband": "5BB",
  "atomofficialpage": "ATOM",
  "fortunebroadband": "Fortune",
  "myanmarnetinternet": "Frontiir",
  "hiinternetwifi": "Hi Internet",
  "kinetic": "Kinetic",
  "maharnetyangon": "Mahar Net",
  "margaglobaltele": "Marga Global Telecom",
  "maxxbfiberinternet": "MaxxB",
  "mbtwifi123": "MBT",
  "mptofficialpage": "MPT",
  "myanmarnet": "Myanmar Net",
  "mmspeednet247": "Myanmar Speed Net",
  "streamnetfiberyangon": "Stream Net",
  "truenet": "TrueNet",
  "truenetisp": "TrueNet",
  "unilinkmyanmar": "Unilink",
  "welinkmyanmaryangon": "Welink"
};

// ----------------------------
// 3️⃣ Collect & Normalize Posts
// ----------------------------
const postsRaw = $input.first().json.data || [];
let posts = [];

for (const data of postsRaw) {
  const uniqueIdRaw = data?.authorMeta?.uniqueId || "";
  const nickNameRaw = data?.authorMeta?.nickName || "";

  const uniqueId = normalizeKey(uniqueIdRaw);
  const nickName = normalizeKey(nickNameRaw);

  let brand =
  brandMap[uniqueId] ||
  brandMap[nickName] ||
  nickNameRaw ||
  uniqueIdRaw;

if (!brand || brand.trim() === "") {
  continue; // skip only empty ones
}

  // ---------------- Metrics ----------------
  const views = toNumber(data.playCount);
  const likes = toNumber(data.diggCount);
  const comments = toNumber(data.commentCount);
  const shares = toNumber(data.shareCount);
  const engagement = likes + comments + shares;
  const engagementRate = views > 0
    ? ((engagement / views) * 100).toFixed(2)
    : 0;

  // ---------------- Post Type ----------------
  let type = "Video";
  if (data?.images?.length) type = "Image";
  else if (!data.video && !data?.images?.length) type = "Text";

  // ---------------- Content ----------------
  let content = data.text || "-";
  if (content.length > 200) {
    content = content.slice(0, 200) + "...";
  }

  // ---------------- Time Info ----------------
  const dateObj = new Date(data.createTime * 1000);
  const hour = dateObj.getHours();
  const bucket = timeBucket(hour);
  const dayType = dayTypeFromTimestamp(dateObj.getTime());

  posts.push({
    brand_name: brand,
    type,
    content,
    views,
    likes,
    comments,
    shares,
    engagement,
    engagement_rate: `${engagementRate}%`,
    postedAt: formatMyanmarDate(dateObj),
    timestamp: dateObj.getTime(),
    hour,
    timeBucket: bucket,
    dayType,
    link: `https://www.tiktok.com/@${uniqueIdRaw}/video/${data.id}`
  });
}

// ----------------------------
// 4️⃣ Aggregate Per Brand
// ----------------------------
const stats = {};

for (const p of posts) {
  if (!stats[p.brand_name]) {
    stats[p.brand_name] = {
      brand_name: p.brand_name,
      post_count: 0,
      total_views: 0,
      total_likes: 0,
      total_comments: 0,
      total_shares: 0,
      total_engagement: 0
    };
  }

  stats[p.brand_name].post_count++;
  stats[p.brand_name].total_views += p.views;
  stats[p.brand_name].total_likes += p.likes;
  stats[p.brand_name].total_comments += p.comments;
  stats[p.brand_name].total_shares += p.shares;
  stats[p.brand_name].total_engagement += p.engagement;
}

// Add engagement rate to summary
Object.values(stats).forEach(b => {
  b.engagement_rate =
    b.total_views > 0
      ? ((b.total_engagement / b.total_views) * 100).toFixed(2) + "%"
      : "0%";
});

// ----------------------------
// 5️⃣ Final Output
// ----------------------------
return [{
  json: {
    generated_at: new Date().toISOString(),
    total_posts: posts.length,
    brands_detected: Object.keys(stats).length,
    posts,
    summary: Object.values(stats)
  }
}];
